[RequireComponent(typeof(Rigidbody))]
public class PhysicsBasics : MonoBehaviour
{
    private Rigidbody rb;

    void Awake()
    {
        rb = GetComponent<Rigidbody>();

        // Rigidbody configuration
        rb.mass = 5f;
        rb.useGravity = true;
        rb.isKinematic = false; // If true, physics won't affect it
        rb.interpolation = RigidbodyInterpolation.Interpolate; // Smooth visual movement
        rb.collisionDetectionMode = CollisionDetectionMode.Continuous; // Better for fast objects
    }

    void FixedUpdate()
    {
        // Apply force in a direction
        rb.AddForce(Vector3.forward * 10f, ForceMode.Force);

        // Apply instant velocity change
        rb.AddForce(Vector3.up * 5f, ForceMode.Impulse);

        // Set velocity directly (overrides physics)
        rb.velocity = new Vector3(5f, rb.velocity.y, 0f);

        // Move to position while respecting collisions
        rb.MovePosition(transform.position + Vector3.right * Time.fixedDeltaTime);

        // Rotate while respecting physics
        rb.MoveRotation(Quaternion.Euler(0f, 45f, 0f));
    }
}

