using UnityEngine;

public class CollisionExamples : MonoBehaviour
{
    [SerializeField] private LayerMask enemyLayer;
    [SerializeField] private float damageRadius = 5f;

    // PHYSICAL COLLISION
    void OnCollisionEnter(Collision collision)
    {
        // Check what we hit by tag
        if (collision.gameObject.CompareTag("Enemy"))
        {
            Debug.Log("Crashed into enemy!");

            // Get impact force
            float impactForce = collision.impulse.magnitude / Time.fixedDeltaTime;
            if (impactForce > 10f)
            {
                Debug.Log("High impact crash!");
            }
        }
    }

    // TRIGGER OVERLAP
    void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Coin"))
        {
            CollectCoin(other.gameObject);
        }

        if (other.CompareTag("DeathZone"))
        {
            Die();
        }
    }

    void OnTriggerStay(Collider other)
    {
        // Damage over time while in lava
        if (other.CompareTag("Lava"))
        {
            TakeDamage(10f * Time.deltaTime);
        }
    }

    // RAYCASTING
    void Update()
    {
        // Shoot a ray from camera through mouse position
        Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
        RaycastHit hit;

        // Check if ray hits anything within 100 units
        if (Physics.Raycast(ray, out hit, 100f))
        {
            Debug.Log($"Looking at: {hit.collider.name}");
            Debug.DrawLine(ray.origin, hit.point, Color.red);

            // Click to interact
            if (Input.GetMouseButtonDown(0))
            {
                InteractWith(hit.collider.gameObject);
            }
        }

        // Ground check with raycast
        bool isGrounded = Physics.Raycast(
            transform.position, 
            Vector3.down, 
            1.1f, // Slightly more than half player height
            LayerMask.GetMask("Ground")
        );

        // Explosion damage — find all enemies in radius
        Collider[] hits = Physics.OverlapSphere(transform.position, damageRadius, enemyLayer);
        foreach (Collider enemy in hits)
        {
            float distance = Vector3.Distance(transform.position, enemy.transform.position);
            float damage = Mathf.Lerp(100f, 10f, distance / damageRadius);
            enemy.GetComponent<Enemy>()?.TakeDamage(damage);
        }
    }

    void CollectCoin(GameObject coin) { Destroy(coin); }
    void Die() { Debug.Log("Player died"); }
    void TakeDamage(float amount) { /* ... */ }
    void InteractWith(GameObject target) { /* ... */ }

    void OnDrawGizmosSelected()
    {
        // Visualize damage radius in editor
        Gizmos.color = Color.yellow;
        Gizmos.DrawWireSphere(transform.position, damageRadius);
    }
}

