public class LayerMaskDemo : MonoBehaviour
{
    // Inspector-friendly layer mask field
    [SerializeField] private LayerMask groundLayer;
    [SerializeField] private LayerMask enemyLayer;

    void Start()
    {
        // Create mask programmatically
        int enemyMask = 1 << LayerMask.NameToLayer("Enemy");
        int groundMask = 1 << LayerMask.NameToLayer("Ground");
        int combinedMask = enemyMask | groundMask; // Both layers

        // Ignore collision between Player and Projectile layers
        Physics.IgnoreLayerCollision(
            LayerMask.NameToLayer("Player"),
            LayerMask.NameToLayer("Projectile"),
            true
        );
    }

    void Update()
    {
        // Raycast that ONLY hits ground layer
        if (Physics.Raycast(transform.position, Vector3.down, out RaycastHit hit, 10f, groundLayer))
        {
            Debug.Log($"Ground distance: {hit.distance}");
        }

        // SphereCast that ignores everything except enemies
        if (Physics.SphereCast(transform.position, 0.5f, transform.forward, out RaycastHit enemyHit, 10f, enemyLayer))
        {
            Debug.Log($"Enemy ahead: {enemyHit.collider.name}");
        }

        // Check multiple layers
        int damageableMask = LayerMask.GetMask("Enemy", "Destructible");
        Collider[] targets = Physics.OverlapSphere(transform.position, 5f, damageableMask);
    }
}

